// --- Drop existing tables to ensure a clean start ---
.drop table SecurityLogs ifexists;

.drop table Communications ifexists;

.drop table VictimCalendar ifexists;

.drop table SupplierRecords ifexists;

// --- Create new tables ---

// SecurityLogs table with PersonID
.create table SecurityLogs (
    Timestamp: datetime,
    PersonID: int,
    LocationID: int,
    EventType: string
);

// Communications table
.create table Communications (
    Timestamp: datetime,
    CommsType: string,
    Sender: string,
    Recipient: string,
    Subject: string,
    Body: string,
    Status: string
);

// VictimCalendar table
.create table VictimCalendar (
    StartTime: datetime,
    EndTime: datetime,
    Subject: string,
    Attendees: dynamic,
    Status: string
);

// SupplierRecords table
.create table SupplierRecords (
    OrderDate: datetime,
    Supplier: string,
    ItemCode: string,
    ItemDescription: string,
    Quantity: int,
    Notes: string
);

.create table SecurityLogs (Timestamp: datetime, CharacterID: int, LocationID: int, EventType: string)

// Step 1: Clear the blank records from the table.
.clear table SecurityLogs data

// Step 2: Ingest the data again, this time specifying the format as 'psv' (pipe-separated).
// This is much safer than using tabs.
.ingest inline into table SecurityLogs with (format = 'psv') <|
2025-10-06T22:30:15Z|1|101|Access Granted
2025-10-06T23:55:45Z|3|105|Movement Detected
2025-10-07T02:15:03Z|2|102|Access Granted

// --- Verification ---

// Step 3: Check that the record count is 3.
SecurityLogs
| count

// Step 4: View the actual data, which should now be populated correctly.
SecurityLogs
| take 10

// ===================================================================
// KQL Data Load Script for "The Oracle of Aetherium"
// This script will wipe all existing data and load the initial story.
// ===================================================================

// 1. Clear Existing Data from Tables
// ------------------------------------
.clear table SecurityLogs data;

.clear table Communications data;

.clear table VictimCalendar data;

.clear table SupplierRecords data;

// 2. Ingest New Story Data
// -----------------------------

// Ingest into SecurityLogs
.ingest inline into table SecurityLogs with (format = 'psv') <|
2025-10-06T22:30:15Z|1|101|Access Granted
2025-10-06T23:55:45Z|3|105|Movement Detected
2025-10-07T02:15:03Z|2|102|Access Granted



// Ingest into Communications
.ingest inline into table Communications with (format = 'psv') <|
"2025-10-06T22:45:10Z"|"TextMessage"|"Marcus Thorne"|"Julian Croft"|""|"You will not erase me. I will ruin you before you ruin me."|"Sent"
"2025-10-06T20:10:00Z"|"Email"|"Evelyn Reed"|"tips@techauditor.com"|"The Real Oracle Story"|"To whom it may concern, the story of Aetherium's 'Oracle' AI is a lie. Julian Croft's groundbreaking success was built on stolen code, my code. He pushed me out of my own company and..."|"Draft"
"2025-10-06T23:40:00Z"|"Email"|"Julian Croft"|"research@medsolutions.com"|"Re: Fwd: Alistair Finch - Urgent Request"|"We're a go. The projections from Aether are clear. Spare no expense, I'm personally funding the next-stage trials for Dr. Finch. Expedite everything."|"Draft"

// Ingest into VictimCalendar
.ingest inline into table VictimCalendar with (format = 'psv') <|
"2025-10-06T16:00:00Z"|"2025-10-06T17:00:00Z"|"Merger Discussion: Aetherium & Nexus Dynamics"|"[\"Julian Croft\", \"Anya Sharma\"]"|"Confirmed"
"2025-10-08T09:00:00Z"|"2025-10-08T10:00:00Z"|"Follow-up: MedSolutions Experimental Trial Shipment"|"[\"Julian Croft\"]"|"Deleted"

// Ingest into SupplierRecords
.ingest inline into table SupplierRecords with (format = 'psv') <|
"2025-09-12T00:00:00Z"|"QuantumChip Co."|"QC-GPU-9980"|"GPU Cluster Upgrade"|32|"Standard procurement"
"2025-09-15T00:00:00Z"|"BioMed Solutions"|"EXP-HTD-42"|"Experimental Cardiotropic Drug (NDA)"|1|"Rush delivery for A.F. Patient confidential."

print "KQL story data has been successfully loaded.";

.alter-merge table Communications policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5);

.alter-merge table SecurityLogs policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5);

.alter-merge table SupplierRecords policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5);

.alter-merge table VictimCalendar policy mirroring dataformat=parquet with (IsEnabled=true, TargetLatencyInMinutes=5);
